/*
 * Normalise the Cloud API response into a single shape the two
 * report nodes can consume, and decide whether the error is worth
 * another attempt.
 *
 * The claim_token is carried through from the claim step: without it
 * the app will refuse to record the outcome.
 */
const PERMANENT = new Set([100, 131008, 131009, 131026, 131047, 131051, 132000, 132001, 132005, 132007, 132012, 133010, 190]);
const TRANSIENT = new Set([1, 2, 4, 80007, 130429, 131000, 131016, 133016]);

const out = [];

for (const item of $input.all()) {
  const claimed = $('Split messages').itemMatching(item.pairedItem?.item ?? 0).json;
  const response = item.json;
  const status = response.statusCode ?? 0;
  const body = response.body ?? {};

  const providerMessageId = body?.messages?.[0]?.id ?? null;

  if (status >= 200 && status < 300 && providerMessageId) {
    out.push({ json: { ok: true, message_id: claimed.id, claim_token: claimed.claim_token, provider_message_id: providerMessageId } });
    continue;
  }

  const code = body?.error?.code;
  let retryable;
  if (TRANSIENT.has(code)) retryable = true;
  else if (PERMANENT.has(code)) retryable = false;
  else if (status === 429 || status >= 500) retryable = true;
  else if (status >= 400) retryable = false;
  else retryable = true;

  out.push({ json: {
    ok: false,
    message_id: claimed.id,
    claim_token: claimed.claim_token,
    error_code: code !== undefined ? String(code) : `http_${status}`,
    error_message: String(body?.error?.error_data?.details ?? body?.error?.message ?? 'Unknown WhatsApp error').slice(0, 2000),
    retryable,
  } });
}

return out;
